   460    inline bool sanitize (hb_sanitize_context_t *c) const
   461    {
   462      TRACE_SANITIZE (this);
   463      if (unlikely (!sanitize_shallow (c))) return_trace (false);
   464
   465      /* Note: for structs that do not reference other structs,
   466       * we do not need to call their sanitize() as we already did
   467       * a bound check on the aggregate array size.  We just include
   468       * a small unreachable expression to make sure the structs
   469       * pointed to do have a simple sanitize(), ie. they do not
   470       * reference other structs via offsets.
   471       */
   472      (void) (false && arrayZ[0].sanitize (c));
   473
   474      return_trace (true);
   475    }
